    // [99] Simbolismo e Parnasianismo
    [99, 'ENEM 2023', 'O Parnasianismo brasileiro caracterizou-se pela busca da perfeição formal. Qual elemento abaixo é considerado essencial para os poetas parnasianos?', 'Olavo Bilac e a defesa do verso livre', 'O engajamento em causas político-sociais', 'O uso de rimas ricas e raras e a precisão métrica', 'A expressão de sentimentos descontrolados', 'A valorização das culturas indígenas e africanas', 'c', 'Os parnasianos adotaram o lema "arte pela arte", buscando extrema rigidez formal, métrica perfeita, vocabulário rebuscado e rimas ricas.', 'fácil', 0],
    [99, 'USP (FUVEST) 2023', 'O Simbolismo, marcado pelo pessimismo e pela fuga da realidade concreta, utilizou largamente quais recursos estilísticos em sua poesia?', 'Objetividade e descrições minuciosas de objetos', 'Musicalidade, sinestesias e aliterações', 'Linguagem coloquial e versos livres', 'Ironia e sarcasmo contra a burguesia', 'Retomada de temas da mitologia grega', 'b', 'Os simbolistas (como Cruz e Sousa) buscavam sugerir os elementos em vez de nomeá-los, abusando de figuras sonoras (aliteração, assonância) e de sentido (sinestesia) para criar musicalidade.', 'médio', 0],
    [99, 'UNICAMP 2024', '"Profissão de Fé", de Olavo Bilac, é frequentemente considerado um manifesto do Parnasianismo. Nele, o trabalho do poeta é comparado ao de um:', 'Sacerdote que prega aos fiéis', 'Pescador lançando redes ao mar', 'Ourives que trabalha minuciosamente uma joia', 'Guerreiro no campo de batalha', 'Agricultor cultivando a terra', 'c', 'Bilac compara o esforço poético ao ofício do ourives, destacando o trabalho lento e minucioso de lapidar a palavra, em busca da perfeição da forma.', 'médio', 0],
    [99, 'UNESP 2024', 'João da Cruz e Sousa, o maior representante do Simbolismo no Brasil, aborda frequentemente em sua obra:', 'A exaltação do progresso científico', 'Temas como o mistério, a morte, a espiritualidade e a cor branca', 'O cotidiano urbano e a vida boêmia', 'A descrição fiel de vasos e estátuas clássicas', 'A vida dos retirantes nordestinos', 'b', 'Cruz e Sousa, o "Cisne Negro", marcou a poesia simbolista com a obsessão pela cor branca, além da exploração do sofrimento, transcendência espiritual e mistério.', 'fácil', 0],
    [99, 'ENEM 2022', 'Embora ambos os movimentos tenham ocorrido simultaneamente no final do século XIX, Parnasianismo e Simbolismo diferem radicalmente em suas bases filosóficas. A oposição principal entre eles pode ser definida como:', 'O Parnasianismo é subjetivo e o Simbolismo é objetivo', 'O Parnasianismo é materialista e descritivo; o Simbolismo é espiritualista e sugestivo', 'O Parnasianismo rejeita a forma e o Simbolismo a cultua', 'Ambos são românticos, mas o Parnasianismo foca na prosa', 'O Parnasianismo foca na musicalidade enquanto o Simbolismo foca na rima', 'b', 'O Parnasianismo lida com o mundo material, buscando descrevê-lo com precisão estatuária. O Simbolismo busca a essência transcendente, a alma das coisas, focando no impreciso e no espiritual.', 'difícil', 1],

